export type Language = 'en' | 'zh';

type Localized<T> = { en: T; zh: T };

export type NodeEvidence = {
  label: Localized<string>;
  url?: string;
  level: string;
};

export type NodeContent = {
  takeaway: Localized<string>;
  keyPoints: Localized<string[]>;
  definition: Localized<string>;
  mechanism: Localized<string[]>;
  applications: Localized<string[]>;
  caseStudy: {
    title: Localized<string>;
    context: Localized<string>;
    lesson: Localized<string>;
  };
  tradeoffs: Localized<string[]>;
  interview: Localized<string[]>;
  pitfalls: Localized<string[]>;
  prerequisites: Localized<string[]>;
  evidence: NodeEvidence[];
  confidence: string;
};

const text = <T,>(en: T, zh: T): Localized<T> => ({ en, zh });
const evidence = (label: string, level: string, url?: string): NodeEvidence => ({ label: text(label, label), level, ...(url ? { url } : {}) });

